/* Globals */

.disabled {
  opacity: 0.5;
  pointer-events: none;
}

/* Page layout */

body {
  --ab-pane-min-width: 240px;
  --booksSplitter-width: var(--ab-pane-min-width);
  --sharedSplitter-height: 50%;
  --ab-cards-pane-min-width: 340px;
  --sharedSplitter-width: var(--ab-cards-pane-min-width);
  --ab-details-pane-min-width: 500px;

  display: grid;
  grid-template: "toolbox toolbox toolbox toolbox toolbox" min-content
                 "books booksSplitter cards sharedSplitter details" minmax(auto, 1fr)
                 / minmax(var(--ab-pane-min-width), var(--booksSplitter-width)) min-content
                   minmax(var(--ab-cards-pane-min-width), var(--sharedSplitter-width)) min-content
                   minmax(var(--ab-details-pane-min-width), 1fr);
  text-shadow: none;
  font-size: 1.1rem;

  &.layout-table {
    grid-template: "toolbox toolbox toolbox" min-content
                   "books booksSplitter cards" minmax(var(--ab-card-min-height), 1fr)
                   "books booksSplitter sharedSplitter" min-content
                   "books booksSplitter details" minmax(auto, var(--sharedSplitter-height))
                   / minmax(var(--ab-pane-min-width), var(--booksSplitter-width)) min-content minmax(var(--ab-details-pane-min-width), 1fr);
  }
}

#dialogStack {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
}

/* Toolbar */

#toolbox {
  grid-area: toolbox;
  font: message-box;
  font-size: 1rem;
}

.toolbarbutton-1:focus-visible {
  outline: var(--focus-outline);
}

#toolbarCreateBook {
  list-style-image: var(--icon-new-address-book);
}

#toolbarCreateContact {
  list-style-image: var(--icon-new-contact);
}

#toolbarCreateList {
  list-style-image: var(--icon-new-user-list);
}

#toolbarImport {
  list-style-image: var(--icon-import);
}

/* Books pane */

#booksPane {
  grid-area: books;
  padding-block-start: 30px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  color: var(--listbox-color);
  background-color: var(--sidebar-background-color, var(--ab-pane-background));
}

#booksSplitter {
  grid-area: booksSplitter;
}

#books {
  flex: 1;
  font-size: 1.1rem;
  overflow-y: auto;
  scroll-behavior: smooth;
  -moz-user-select: none;

  &:focus-visible {
    outline: none;
  }

  &,
  & ul {
    margin: 0;
    padding: 0;
    list-style: none;
  }
}

#allAddressBooks {
  margin-block-end: 10px;
}

.bookRow-container,
.listRow-container {
  display: flex;
  align-items: center;
  margin-inline: 6px;
  border-radius: var(--button-border-radius);
  -moz-context-properties: fill, stroke;
  fill: color-mix(in srgb, var(--ab-icons-color) 20%, transparent);
  stroke: var(--ab-icons-color);
  cursor: default;

  #books:not(:focus) :where(.bookRow, .listRow).selected > & {
    background-color: var(--listbox-selected-bg);
    outline: var(--listbox-selected-outline);
    outline-offset: -2px;
  }

  :where(.bookRow, .listRow) > &:hover {
    background-color: var(--listbox-hover);
  }

  #books:focus :where(.bookRow, .listRow).selected > & {
    background-color: var(--listbox-focused-selected-bg);
    color: var(--listbox-selected-color);
    fill: color-mix(in srgb, currentColor 20%, transparent);
    stroke: currentColor;
  }

  :where(.bookRow, .listRow).drop-target > & {
    background-color: var(--selected-item-color);
    color: var(--selected-item-text-color);
  }
}

#books:focus .selected .twisty {
  stroke: currentColor;
}

.bookRow {
  .twisty {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--list-item-buttons-size);
    height: var(--list-item-buttons-size);
    -moz-context-properties: stroke;
    stroke: var(--ab-icons-color);
  }

  &:not(.children) .twisty-icon {
    display: none;
  }

  &.children.collapsed {
    .twisty-icon {
      transform: rotate(-90deg);
    }

    &:dir(rtl) {
      .twisty-icon {
        transform: rotate(90deg);
      }
    }
  }
}

.bookRow-icon,
.listRow-icon {
  width: 16px;
  height: 16px;
  background-image: var(--addressbook-tree-ab);
  background-position: center center;
  background-repeat: no-repeat;
}

.bookRow.remote .bookRow-icon {
  background-image: var(--addressbook-tree-remote);
}

